    """Continue diagonal monochrome strokes outward across the uniform background."""
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0]) if out else 0
    if not h or not w:
        return out
    from collections import Counter
    bg = Counter(v for row in out for v in row).most_common(1)[0][0]
    segments = []
    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = out[r][c]
                if color == bg:
                    continue
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and out[pr][pc] == color:
                    continue
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == color:
                    rr += dr
                    cc += dc
                er, ec = rr - dr, cc - dc
                length = max(abs(er-r), abs(ec-c)) + 1
                if length < 2:
                    continue
                # Two-color corner motifs are markers, not strokes to extrapolate.
                def adjacent_other(y, x):
                    return any(0 <= y+dy < h and 0 <= x+dx < w
                               and out[y+dy][x+dx] not in (bg, color)
                               for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)))
                if adjacent_other(r, c) and adjacent_other(er, ec):
                    continue
                segments.append((r, c, er, ec, dr, dc, color))
    for r, c, er, ec, dr, dc, color in segments:
        for rr, cc, ar, ac in ((r, c, -dr, -dc), (er, ec, dr, dc)):
            rr += ar
            cc += ac
            while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                out[rr][cc] = color
                rr += ar
                cc += ac
    return out
